// Static check of the T8 step table. Not an experiment version.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/check_table_t8_r1.mjs <table.json>
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const tablePath = process.argv[2];
if (!tablePath) {
  process.stderr.write('usage: node26 work/scripts/check_table_t8_r1.mjs <table.json>\n');
  process.exit(2);
}
const table = JSON.parse(readFileSync(resolve(tablePath), 'utf8'));
const problems = [];
function bad(msg) { problems.push(msg); }

const steps = table.steps || [];
const ids = steps.map((s) => s.id);
const seen = new Set();
for (const id of ids) {
  if (!id) bad('blank id');
  else if (seen.has(id)) bad('duplicate id ' + id);
  else seen.add(id);
}
const byId = new Map(steps.map((s) => [s.id, s]));
const REQUIRED = ['id', 'action', 'who', 'phase', 'expect'];
for (const step of steps) {
  for (const field of REQUIRED) {
    if (!(field in step) || step[field] == null) bad(step.id + ' missing ' + field);
  }
  if (!Array.isArray(step.who) || step.who.length === 0) bad(step.id + ' who empty');
  if (step.action === 'key' && !step.key) bad(step.id + ' key missing');
  if (step.action === 'edge' && (!step.key || !step.dir)) bad(step.id + ' edge key/dir missing');
  if (step.action === 'dial' && !step.dial) bad(step.id + ' dial missing');
  if (step.action === 'dial-until' && !(step.bound > 0) && !(step.until)) bad(step.id + ' dial-until bound');
  const blob = JSON.stringify(step);
  if (blob.includes('unresolved')) bad(step.id + ' unresolved placeholder');
  if (blob.includes('halfSingle')) bad(step.id + ' misleading preset halfSingle');
  if (step.expect && JSON.stringify(step.expect) === '[]') bad(step.id + ' empty check');
}

function whoKey(step) {
  return [...step.who].sort().join(',');
}
function sameWho(group, label) {
  const sets = new Map();
  for (const step of group) {
    const key = whoKey(step);
    if (!sets.has(key)) sets.set(key, []);
    sets.get(key).push(step.id);
  }
  if (sets.size > 1) bad(label + ' who sets differ ' + [...sets.keys()].join(' | '));
}
const halfPress = steps.filter((s) => !s.editor && (s.action === 'key' || s.action === 'dial') && s.phase === 'main');
const edges = steps.filter((s) => s.action === 'edge');
const exits = steps.filter((s) => s.action === 'save-identity' || (s.id && s.id.startsWith('save-')));
sameWho(halfPress, 'half-press keys');
sameWho(edges, 'edges');
sameWho(exits, 'save steps');
for (const step of edges) {
  for (const role of ['k2', 'c1', 'c2']) {
    if (!step.who.includes(role)) bad('edge ' + step.id + ' missing ' + role);
  }
}
for (const step of halfPress) {
  for (const role of ['k1', 'k2', 'c1', 'c2']) {
    if (!step.who.includes(role)) bad('half-press ' + step.id + ' missing ' + role);
  }
}

const listed = new Set((table.editorKeys || []).map((e) => e.id));
const editorSteps = steps.filter((s) => s.editor);
for (const step of editorSteps) {
  if (!listed.has(step.id)) bad('editor key not listed ' + step.id);
  if (step.who.includes('k1') || step.who.includes('k2')) bad('K2 runs editor key ' + step.id);
}
for (const id of listed) {
  if (!byId.has(id) || !byId.get(id).editor) bad('listed editor key is not an editor step ' + id);
}

function walkRefs(value, step, field, path) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return;
  if (value.ref) {
    const id = value.step || step.id;
    if (id !== step.id) bad(step.id + ' ' + field + ' reference ' + id + ' is not the same step');
    if (!byId.has(id)) bad(step.id + ' missing reference step ' + id);
  }
  if (value.from) {
    const id = value.step || step.id;
    if (id !== step.id) bad(step.id + ' cross-step from ' + id);
  }
  for (const [k, v] of Object.entries(value)) {
    if (k === 'ref' || k === 'step' || k === 'from') continue;
    walkRefs(v, step, field, path + '.' + k);
  }
}
for (const step of steps) {
  if (!step.expect) continue;
  for (const [field, value] of Object.entries(step.expect)) walkRefs(value, step, field, field);
}

function mirrorOf(step) {
  const m = step.expect && step.expect.mirror;
  if (Array.isArray(m)) return m;
  return null;
}
function u16(m, off) { return m[off] | (m[off + 1] << 8); }

const eok = byId.get('e-ok');
const pmenu = byId.get('p-menu');
const czone = byId.get('c-zone');
const cdims = byId.get('c-dims');
const cs1 = byId.get('c-s1');
if (!eok || !pmenu || !czone || !cdims || !cs1) bad('missing C1 or bank steps');
const mE = eok && mirrorOf(eok);
const mP = pmenu && mirrorOf(pmenu);
const mC = cdims && mirrorOf(cdims);
if (!mE || mE.length !== 55) bad('e-ok mirror is not 55 bytes');
if (!mP || mP.length !== 55) bad('p-menu mirror is not 55 bytes');
if (!mC || mC.length !== 55) bad('c-dims mirror is not 55 bytes');
if (mE && mP) {
  if (mE[1] !== mP[1]) bad('bank-1 zone changed across the EXIF-6 edit');
  if (u16(mE, 12) !== u16(mP, 12)) bad('bank-1 position changed across the EXIF-6 edit');
  if (u16(mE, 20) === u16(mP, 20)) bad('bank-5 position did not change across the EXIF-6 edit');
}
if (mC) {
  if (mC[1] === 2) bad('C1 mirror is still Small (type 2)');
  if (mC[1] !== 6) bad('C1 mirror zone type is ' + mC[1] + ' not 6');
  if (mC[24] !== 5 || mC[25] !== 7) bad('C1 dimensions are not [5,7]');
  if (mP && (mC[5] !== mP[5] || u16(mC, 20) !== u16(mP, 20))) bad('C1 mirror discards the bank-5 edit');
  if (mE && (mC[1] === mE[1])) bad('C1 step did not change the bank-1 type');
}
if (cs1) {
  if (cs1.key !== 's1' || cs1.action === 'edge') bad('S1 exit is not a real S1 key');
  if (!cs1.editor) bad('S1 exit is not an editor key');
  const idx = steps.indexOf(cs1);
  const prev = steps[idx - 1];
  if (!prev || !prev.editor) bad('S1 exit does not follow an editor step');
  if (!prev.expect || prev.expect.flag !== 1) bad('S1 exit is not inside the open editor');
  if (!prev.expect || prev.expect.screen !== 'direct') bad('S1 exit does not follow the direct editor');
}

const save = byId.get('save-identity');
if (!save || save.action !== 'save-identity') bad('save is not identity-guided');
if (save && save.who && (!save.who.includes('k2') || !save.who.includes('c1'))) bad('save who mismatch');
if (save && (!save.expect || !save.expect.afTabHeader || !save.expect.highlightRow)) bad('save identity fields');
if (save && save.expect && save.expect.baselines && save.expect.baselines.length < 3) bad('save baselines incomplete');
if (table.afTabHeader !== 'bb086a5b20fe141fc7db882c015fb47fa34bccd9d86ab709799ef8bb8324225c') bad('AF tab hash is not the T6 header');

const report = {
  ok: problems.length === 0,
  table: table.table,
  steps: steps.length,
  editorKeys: editorSteps.map((s) => s.id),
  edges: edges.map((s) => s.id),
  halfPress: halfPress.map((s) => s.id),
  problems,
};
const out = resolve('work/out/table-check-t8-r1.json');
writeFileSync(out, JSON.stringify(report, null, 2) + '\n');
process.stdout.write(JSON.stringify({ ok: report.ok, problems: problems.length, steps: steps.length }) + '\n');
if (problems.length) {
  for (const p of problems) process.stderr.write(p + '\n');
  process.exit(1);
}
